650|        return Z_STREAM_ERROR;
651|
652|    /* free memory and close file */
653|    if (state->size) {
654|        inflateEnd(&(state->strm));
655|        free(state->out);
656|        free(state->in);
657|    }
658|    err = state->err == Z_BUF_ERROR ? Z_BUF_ERROR : Z_OK;
659|    gz_error(state, Z_OK, NULL);
660|    free(state->path);
661|    ret = close(state->fd);
662|    free(state);
