172|/* Decompress from input to the provided next_out and avail_out in the state.
173|   On return, state->x.have and state->x.next point to the just decompressed
174|   data. If the gzip stream completes, state->how is reset to LOOK to look for
175|   the next gzip stream or raw data, once state->x.have is depleted. Returns 0
176|   on success, -1 on failure. If EOF is reached when looking for more input to
177|   complete the gzip member, then an unexpected end of file error is raised.
178|   If there is no more input, but state->again is true, then EOF has not been
179|   reached, and no error is raised. */
180|local int gz_decomp(gz_statep state) {
181|    int ret = Z_OK;
182|    unsigned had;
183|    z_streamp strm = &(state->strm);
184|
185|    /* fill output buffer up to end of deflate stream */
186|    had = strm->avail_out;
187|    do {
188|        /* get more input for inflate() */
189|        if (strm->avail_in == 0 && gz_avail(state) == -1) {
190|            ret = state->err;
191|            break;
192|        }
193|        if (strm->avail_in == 0) {
194|            if (!state->again)
195|                gz_error(state, Z_BUF_ERROR, "unexpected end of file");
196|            break;
197|        }
198|
199|        /* decompress and handle errors */
200|        ret = inflate(strm, Z_NO_FLUSH);
201|        if (strm->avail_out < had)
202|            /* any decompressed data marks this as a real gzip stream */
203|            state->junk = 0;
204|        if (ret == Z_STREAM_ERROR || ret == Z_NEED_DICT) {
205|            gz_error(state, Z_STREAM_ERROR,
206|                     "internal error: inflate stream corrupt");
207|            break;
208|        }
209|        if (ret == Z_MEM_ERROR) {
210|            gz_error(state, Z_MEM_ERROR, "out of memory");
211|            break;
212|        }
213|        if (ret == Z_DATA_ERROR) {              /* deflate stream invalid */
214|            if (state->junk == 1) {             /* trailing garbage is ok */
215|                strm->avail_in = 0;
216|                state->eof = 1;
217|                state->how = LOOK;
218|                ret = Z_OK;
219|                break;
220|            }
221|            gz_error(state, Z_DATA_ERROR,
222|                     strm->msg == NULL ? "compressed data error" : strm->msg);
223|            break;
224|        }
225|    } while (strm->avail_out && ret != Z_STREAM_END);
226|
227|    /* update available output */
228|    state->x.have = had - strm->avail_out;
229|    state->x.next = strm->next_out - state->x.have;
230|
231|    /* if the gzip stream completed successfully, look for another */
232|    if (ret == Z_STREAM_END) {
233|        state->junk = 0;
234|        state->how = LOOK;
235|        return 0;
236|    }
237|
238|    /* return decompression status */
239|    return ret != Z_OK ? -1 : 0;
240|}
