242|/* Fetch data and put it in the output buffer.  Assumes state->x.have is 0.
243|   Data is either copied from the input file or decompressed from the input
244|   file depending on state->how.  If state->how is LOOK, then a gzip header is
245|   looked for to determine whether to copy or decompress.  Returns -1 on error,
246|   otherwise 0.  gz_fetch() will leave state->how as COPY or GZIP unless the
247|   end of the input file has been reached and all data has been processed.  */
248|local int gz_fetch(gz_statep state) {
249|    z_streamp strm = &(state->strm);
250|
251|    do {
252|        switch(state->how) {
253|        case LOOK:      /* -> LOOK, COPY (only if never GZIP), or GZIP */
254|            if (gz_look(state) == -1)
255|                return -1;
256|            if (state->how == LOOK)
257|                return 0;
258|            break;
259|        case COPY:      /* -> COPY */
260|            if (gz_load(state, state->out, state->size << 1, &(state->x.have))
261|                    == -1)
262|                return -1;
263|            state->x.next = state->out;
264|            return 0;
265|        case GZIP:      /* -> GZIP or LOOK (if end of gzip stream) */
266|            strm->avail_out = state->size << 1;
267|            strm->next_out = state->out;
268|            if (gz_decomp(state) == -1)
269|                return -1;
270|        }
271|    } while (state->x.have == 0 && (!state->eof || strm->avail_in));
272|    return 0;
273|}
