391|/* -- see zlib.h -- */
392|int ZEXPORT gzread(gzFile file, voidp buf, unsigned len) {
393|    gz_statep state;
394|
395|    /* get internal structure and check that it's for reading */
396|    if (file == NULL)
397|        return -1;
398|    state = (gz_statep)file;
399|    if (state->mode != GZ_READ)
400|        return -1;
401|
402|    /* check that there was no (serious) error */
403|    if (state->err != Z_OK && state->err != Z_BUF_ERROR && !state->again)
404|        return -1;
405|    gz_error(state, Z_OK, NULL);
406|
407|    /* since an int is returned, make sure len fits in one, otherwise return
408|       with an error (this avoids a flaw in the interface) */
409|    if ((int)len < 0) {
410|        gz_error(state, Z_STREAM_ERROR, "request does not fit in an int");
411|        return -1;
412|    }
413|
414|    /* read len or fewer bytes to buf */
415|    len = gz_read(state, buf, len);
416|
417|    /* check for an error */
418|    if (len == 0) {
419|        if (state->err != Z_OK && state->err != Z_BUF_ERROR)
420|            return -1;
421|        if (state->again) {
422|            /* non-blocking input stalled after some input was read, but no
423|               uncompressed bytes were produced -- let the application know
424|               this isn't EOF */
425|            gz_error(state, Z_ERRNO, zstrerror());
426|            return -1;
427|        }
428|    }
429|
430|    /* return the number of bytes read */
431|    return (int)len;
432|}
