434|/* -- see zlib.h -- */
435|z_size_t ZEXPORT gzfread(voidp buf, z_size_t size, z_size_t nitems,
436|                         gzFile file) {
437|    z_size_t len;
438|    gz_statep state;
439|
440|    /* get internal structure and check that it's for reading */
441|    if (file == NULL)
442|        return 0;
443|    state = (gz_statep)file;
444|    if (state->mode != GZ_READ)
445|        return 0;
446|
447|    /* check that there was no (serious) error */
448|    if (state->err != Z_OK && state->err != Z_BUF_ERROR && !state->again)
449|        return 0;
450|    gz_error(state, Z_OK, NULL);
451|
452|    /* compute bytes to read -- error on overflow */
453|    len = nitems * size;
454|    if (size && len / size != nitems) {
455|        gz_error(state, Z_STREAM_ERROR, "request does not fit in a size_t");
456|        return 0;
457|    }
458|
459|    /* read len or fewer bytes to buf, return the number of full items read */
460|    return len ? gz_read(state, buf, len) / size : 0;
461|}
