469|int ZEXPORT gzgetc(gzFile file) {
470|    unsigned char buf[1];
471|    gz_statep state;
472|
473|    /* get internal structure and check that it's for reading */
474|    if (file == NULL)
475|        return -1;
476|    state = (gz_statep)file;
477|    if (state->mode != GZ_READ)
478|        return -1;
479|
480|    /* check that there was no (serious) error */
481|    if (state->err != Z_OK && state->err != Z_BUF_ERROR && !state->again)
482|        return -1;
483|    gz_error(state, Z_OK, NULL);
