500|/* -- see zlib.h -- */
501|int ZEXPORT gzungetc(int c, gzFile file) {
502|    gz_statep state;
503|
504|    /* get internal structure and check that it's for reading */
505|    if (file == NULL)
506|        return -1;
507|    state = (gz_statep)file;
508|    if (state->mode != GZ_READ)
509|        return -1;
510|
511|    /* in case this was just opened, set up the input buffer */
512|    if (state->how == LOOK && state->x.have == 0)
513|        (void)gz_look(state);
514|
515|    /* check that there was no (serious) error */
516|    if (state->err != Z_OK && state->err != Z_BUF_ERROR && !state->again)
517|        return -1;
518|    gz_error(state, Z_OK, NULL);
519|
520|    /* process a skip request */
521|    if (state->skip && gz_skip(state) == -1)
522|        return -1;
523|
524|    /* can't push EOF */
525|    if (c < 0)
526|        return -1;
527|
528|    /* if output buffer empty, put byte at end (allows more pushing) */
529|    if (state->x.have == 0) {
530|        state->x.have = 1;
531|        state->x.next = state->out + (state->size << 1) - 1;
532|        state->x.next[0] = (unsigned char)c;
533|        state->x.pos--;
534|        state->past = 0;
535|        return c;
536|    }
537|
538|    /* if no room, give up (must have already done a gzungetc()) */
539|    if (state->x.have == (state->size << 1)) {
540|        gz_error(state, Z_DATA_ERROR, "out of room to push characters");
541|        return -1;
542|    }
543|
544|    /* slide output data if needed and insert byte before existing data */
545|    if (state->x.next == state->out) {
546|        unsigned char *src = state->out + state->x.have;
547|        unsigned char *dest = state->out + (state->size << 1);
548|
549|        while (src > state->out)
550|            *--dest = *--src;
551|        state->x.next = dest;
552|    }
553|    state->x.have++;
554|    state->x.next--;
