562|char * ZEXPORT gzgets(gzFile file, char *buf, int len) {
563|    unsigned left, n;
564|    char *str;
565|    unsigned char *eol;
566|    gz_statep state;
567|
568|    /* check parameters, get internal structure, and check that it's for
569|       reading */
570|    if (file == NULL || buf == NULL || len < 1)
571|        return NULL;
572|    state = (gz_statep)file;
573|    if (state->mode != GZ_READ)
574|        return NULL;
575|
576|    /* check that there was no (serious) error */
577|    if (state->err != Z_OK && state->err != Z_BUF_ERROR && !state->again)
578|        return NULL;
579|    gz_error(state, Z_OK, NULL);
580|
581|    /* process a skip request */
582|    if (state->skip && gz_skip(state) == -1)
583|        return NULL;
584|
585|    /* copy output up to a new line, len-1 bytes, or there is no more output,
586|       whichever comes first */
587|    str = buf;
588|    left = (unsigned)len - 1;
589|    if (left) do {
590|        /* assure that something is in the output buffer */
591|        if (state->x.have == 0 && gz_fetch(state) == -1)
592|            break;                      /* error */
593|        if (state->x.have == 0) {       /* end of file */
594|            state->past = 1;            /* read past end */
595|            break;                      /* return what we have */
596|        }
597|
598|        /* look for end-of-line in current output buffer */
599|        n = state->x.have > left ? left : state->x.have;
600|        eol = (unsigned char *)memchr(state->x.next, '\n', n);
601|        if (eol != NULL)
602|            n = (unsigned)(eol - state->x.next) + 1;
603|
604|        /* copy through end-of-line, or remainder if not found */
605|        memcpy(buf, state->x.next, n);
606|        state->x.have -= n;
607|        state->x.next += n;
608|        state->x.pos += n;
609|        left -= n;
610|        buf += n;
611|    } while (left && eol == NULL);
612|
613|    /* append a terminating zero to the string (we don't check for a zero in
614|       the contents, let the user worry about that) -- return the terminated
615|       string, or if nothing was read, NULL */
616|    if (buf == str)
617|        return NULL;
618|    buf[0] = 0;
619|    return str;
620|}
