622|/* -- see zlib.h -- */
623|int ZEXPORT gzdirect(gzFile file) {
624|    gz_statep state;
625|
626|    /* get internal structure */
627|    if (file == NULL)
628|        return 0;
629|    state = (gz_statep)file;
630|
631|    /* if the state is not known, but we can find out, then do so (this is
632|       mainly for right after a gzopen() or gzdopen()) */
633|    if (state->mode == GZ_READ && state->how == LOOK && state->x.have == 0)
634|        (void)gz_look(state);
635|
636|    /* return 1 if transparent, 0 if processing a gzip stream */
637|    return state->direct == 1;
