640|/* -- see zlib.h -- */
641|int ZEXPORT gzclose_r(gzFile file) {
642|    int ret, err;
643|    gz_statep state;
644|
645|    /* get internal structure and check that it's for reading */
646|    if (file == NULL)
647|        return Z_STREAM_ERROR;
648|    state = (gz_statep)file;
649|    if (state->mode != GZ_READ)
650|        return Z_STREAM_ERROR;
651|
652|    /* free memory and close file */
653|    if (state->size) {
654|        inflateEnd(&(state->strm));
655|        free(state->out);
656|        free(state->in);
657|    }
658|    err = state->err == Z_BUF_ERROR ? Z_BUF_ERROR : Z_OK;
659|    gz_error(state, Z_OK, NULL);
660|    free(state->path);
661|    ret = close(state->fd);
662|    free(state);
663|    return ret ? Z_ERRNO : err;
